(function(){'use strict';const canvas=document.getElementById('ink-particles');if(!canvas)return;const prefersReduced=window.matchMedia('(prefers-reduced-motion: reduce)');const cfg={density:0.00008,max:90,speed:0.35,sizeMin:1.0,sizeMax:3.4,link:true,linkDistance:130,follow:true,followStrength:0.06,trail:true,ripple:true,rippleMax:8,mobile:'low'};const state={ctx:canvas.getContext('2d'),width:0,height:0,dpr:1,particles:[],ripples:[],pointer:{x:-9999,y:-9999,px:-9999,py:-9999,active:false},raf:0,running:false,calm:false,disabled:false,last:0,ink:{r:28,g:26,b:23},silver:{r:176,g:138,b:62}};function readConfig(){const dataNode=document.getElementById('site-data');let raw={};try{raw=(JSON.parse((dataNode&&dataNode.textContent)||'{}').particles)||{};}catch(e){raw={};}
Object.keys(cfg).forEach((key)=>{if(raw[key]!==undefined)cfg[key]=raw[key];});if(Array.isArray(cfg.size)&&cfg.size.length===2){cfg.sizeMin=cfg.size[0];cfg.sizeMax=cfg.size[1];}}
function isMobile(){return window.matchMedia('(max-width: 820px)').matches||/Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent||'');}
function palette(){const styles=getComputedStyle(document.documentElement);const parse=(value,fallback)=>{const hex=(value||'').trim().replace('#','');if(!/^[0-9a-f]{6}$/i.test(hex))return fallback;const num=parseInt(hex,16);return{r:(num>>16)&255,g:(num>>8)&255,b:num&255};};state.ink=parse(styles.getPropertyValue('--ink'),{r:28,g:26,b:23});state.silver=parse(styles.getPropertyValue('--silver'),{r:176,g:138,b:62});}
function targetCount(){let count=Math.round(state.width*state.height*cfg.density);count=Math.min(count,cfg.max);if(isMobile()){if(cfg.mobile==='off')return 0;if(cfg.mobile==='low')count=Math.round(count*0.4);}
return Math.max(0,count);}
function resize(){state.dpr=Math.min(window.devicePixelRatio||1,2);state.width=window.innerWidth;state.height=window.innerHeight;canvas.width=Math.round(state.width*state.dpr);canvas.height=Math.round(state.height*state.dpr);state.ctx.setTransform(state.dpr,0,0,state.dpr,0,0);spawn();}
function spawn(){const count=targetCount();if(!count){state.particles=[];state.disabled=true;return;}
state.disabled=false;state.particles=Array.from({length:count},()=>create());}
function create(x,y){const silver=Math.random()<0.28;return{x:x!==undefined?x:Math.random()*state.width,y:y!==undefined?y:Math.random()*state.height,vx:(Math.random()-0.5)*cfg.speed,vy:(Math.random()-0.5)*cfg.speed,size:cfg.sizeMin+Math.random()*Math.max(0.1,cfg.sizeMax-cfg.sizeMin),alpha:0.24+Math.random()*0.4,silver:silver,seed:Math.random()*1000};}
function step(delta){const p=state.pointer;const list=state.particles;for(let i=0;i<list.length;i+=1){const particle=list[i];particle.x+=particle.vx*delta;particle.y+=particle.vy*delta;particle.seed+=delta*0.01;if(particle.x<-20)particle.x=state.width+20;if(particle.x>state.width+20)particle.x=-20;if(particle.y<-20)particle.y=state.height+20;if(particle.y>state.height+20)particle.y=-20;if(cfg.follow&&p.active){const dx=p.x-particle.x;const dy=p.y-particle.y;const distance=Math.hypot(dx,dy);if(distance<190&&distance>0.001){const pull=(1-distance/190)*cfg.followStrength*delta*60;particle.vx+=(dx/distance)*pull*0.06;particle.vy+=(dy/distance)*pull*0.06;particle.vx+=(p.x-p.px)*0.00035;particle.vy+=(p.y-p.py)*0.00035;}}
particle.vx*=0.995;particle.vy*=0.995;const speed=Math.hypot(particle.vx,particle.vy);const limit=cfg.speed*2.4;if(speed>limit){particle.vx=(particle.vx/speed)*limit;particle.vy=(particle.vy/speed)*limit;}
if(speed<0.02){particle.vx+=(Math.random()-0.5)*0.02;particle.vy+=(Math.random()-0.5)*0.02;}}}
function draw(){const ctx=state.ctx;const ink=state.ink;const silver=state.silver;if(cfg.trail){ctx.globalCompositeOperation='destination-out';ctx.fillStyle='rgba(0,0,0,0.14)';ctx.fillRect(0,0,state.width,state.height);ctx.globalCompositeOperation='source-over';}else{ctx.clearRect(0,0,state.width,state.height);}
const list=state.particles;if(cfg.link&&list.length<=140){const maxDistance=cfg.linkDistance;for(let i=0;i<list.length;i+=1){for(let j=i+1;j<list.length;j+=1){const a=list[i];const b=list[j];const dx=a.x-b.x;const dy=a.y-b.y;const distanceSq=dx*dx+dy*dy;if(distanceSq>maxDistance*maxDistance)continue;const distance=Math.sqrt(distanceSq);const alpha=(1-distance/maxDistance)*0.13;ctx.strokeStyle='rgba('+ink.r+','+ink.g+','+ink.b+','+alpha.toFixed(3)+')';ctx.lineWidth=0.6;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}}}
for(let i=0;i<list.length;i+=1){const particle=list[i];const wobble=1+Math.sin(particle.seed)*0.18;const color=particle.silver?silver:ink;ctx.beginPath();ctx.fillStyle='rgba('+color.r+','+color.g+','+color.b+','+particle.alpha.toFixed(3)+')';ctx.arc(particle.x,particle.y,particle.size*wobble,0,Math.PI*2);ctx.fill();}
for(let i=state.ripples.length-1;i>=0;i-=1){const ripple=state.ripples[i];ripple.radius+=ripple.speed;ripple.alpha*=0.955;if(ripple.alpha<0.012||ripple.radius>ripple.max){state.ripples.splice(i,1);continue;}
ctx.strokeStyle='rgba('+silver.r+','+silver.g+','+silver.b+','+ripple.alpha.toFixed(3)+')';ctx.lineWidth=ripple.width;ctx.beginPath();ctx.arc(ripple.x,ripple.y,ripple.radius,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='rgba('+ink.r+','+ink.g+','+ink.b+','+(ripple.alpha*0.5).toFixed(3)+')';ctx.lineWidth=ripple.width*0.5;ctx.beginPath();ctx.arc(ripple.x,ripple.y,ripple.radius*0.62,0,Math.PI*2);ctx.stroke();}}
function loop(time){if(!state.running)return;if(time-state.last>26){const delta=Math.min(2.4,(time-state.last)/16.666);state.last=time;step(delta);draw();}
state.raf=requestAnimationFrame(loop);}
function start(){if(state.running||state.disabled||state.calm)return;state.running=true;state.last=performance.now();state.raf=requestAnimationFrame(loop);}
function stop(){state.running=false;if(state.raf)cancelAnimationFrame(state.raf);state.raf=0;}
function applyCalm(){state.calm=document.documentElement.getAttribute('data-calm')==='on'||prefersReduced.matches;if(state.calm){stop();state.ctx.clearRect(0,0,state.width,state.height);}else if(!document.hidden){start();}}
function addRipple(x,y){if(!cfg.ripple)return;if(state.ripples.length>=cfg.rippleMax)state.ripples.shift();state.ripples.push({x:x,y:y,radius:2,max:150+Math.random()*90,speed:1.9+Math.random()*1.2,alpha:0.5,width:1.2});for(let i=0;i<3;i+=1){const angle=Math.random()*Math.PI*2;const particle=create(x,y);particle.vx=Math.cos(angle)*(0.6+Math.random());particle.vy=Math.sin(angle)*(0.6+Math.random());state.particles.push(particle);if(state.particles.length>cfg.max*1.3)state.particles.shift();}
start();}
document.addEventListener('DOMContentLoaded',()=>{readConfig();palette();resize();applyCalm();if(!state.calm)start();window.addEventListener('pointermove',(event)=>{state.pointer.px=state.pointer.x;state.pointer.py=state.pointer.y;state.pointer.x=event.clientX;state.pointer.y=event.clientY;state.pointer.active=true;},{passive:true});window.addEventListener('pointerleave',()=>{state.pointer.active=false;});window.addEventListener('pointerdown',(event)=>{const tag=(event.target.tagName||'').toLowerCase();if(tag==='input'||tag==='textarea'||tag==='button'||tag==='a')return;addRipple(event.clientX,event.clientY);},{passive:true});let resizeTimer=0;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{resize();if(state.calm){state.ctx.clearRect(0,0,state.width,state.height);}},200);});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else if(!state.calm)start();});document.addEventListener('ink:reading',applyCalm);document.addEventListener('ink:mode',palette);if(prefersReduced&&prefersReduced.addEventListener)prefersReduced.addEventListener('change',applyCalm);window.InkRipple=addRipple;});})();